from collections import OrderedDict
from typing import Callable, Dict, Optional

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock: Callable[[], float]):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.cache: OrderedDict[str, (float, object)] = OrderedDict()
        self.stats = {"hits": 0, "misses": 0, "evictions": 0, "expirations": 0}

    def _remove_expired(self) -> None:
        now = self.clock()
        while self.cache and self.cache[next(iter(self.cache))] [0] <= now:
            key, _ = self.cache.popitem(last=False)
            self.stats["expirations"] += 1

    def _evict(self) -> None:
        key, _ = self.cache.popitem(last=False)
        self.stats["evictions"] += 1

    def put(self, key: str, value: object) -> None:
        if self.capacity == 0:
            return
        now = self.clock()
        self._remove_expired()
        if len(self.cache) >= self.capacity:
            self._evict()
        self.cache[key] = (now + self.ttl, value)

    def get(self, key: str, default: Optional[object] = None) -> Optional[object]:
        if self.capacity == 0:
            self.stats["misses"] += 1
            return default
        now = self.clock()
        self._remove_expired()
        if key in self.cache:
            expiry, value = self.cache.pop(key)
            if expiry > now:
                self.cache[key] = (expiry, value)
                self.stats["hits"] += 1
                return value
            else:
                self.stats["expirations"] += 1
        self.stats["misses"] += 1
        return default

    def __len__(self) -> int:
        now = self.clock()
        return sum(1 for expiry, _ in self.cache.values() if expiry > now)

    def stats(self) -> Dict[str, int]:
        return self.stats.copy()
