from typing import Callable

class TokenBucket:
    def __init__(self, capacity: float, refill_per_sec: float, clock: Callable[[], float]):
        self.capacity = capacity
        self.refill_per_sec = refill_per_sec
        self.clock = clock
        self.tokens = capacity
        self.last_refill = clock()

    @property
    def tokens(self) -> float:
        self.refill()
        return self._tokens

    @tokens.setter
    def tokens(self, value: float):
        self._tokens = value

    def refill(self) -> None:
        current_time = self.clock()
        elapsed_time = current_time - self.last_refill
        self.last_refill = current_time
        refill_amount = elapsed_time * self.refill_per_sec
        self._tokens = min(self.capacity, self._tokens + refill_amount)

    def allow(self, cost: float = 1) -> bool:
        self.refill()
        if self._tokens >= cost:
            self._tokens -= cost
            return True
        return False
